const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let inputLines = [];
rl.on('line', (line) => {
    inputLines.push(line);
}).on('close', () => {
    solve();
});

function solve() {
    const data = inputLines.join(' ').split(/\s+/).map(Number);
    if (data.length < 2) return;

    const n = data[0];
    const m = data[1];
    let idx = 2;
    const a = data.slice(idx, idx + n);
    idx += n;
    const b = data.slice(idx, idx + n);

    const INF = 1e18;
    let dp = new Array(n + 1).fill(INF);
    dp[0] = 0;

    // DP for one period of length n
    for (let i = 0; i < n; i++) {
        const next = new Array(n + 1).fill(INF);
        for (let bal = 0; bal <= n; bal++) {
            if (dp[bal] === INF) continue;
            // Open bracket
            if (bal + 1 <= n) {
                next[bal + 1] = Math.min(next[bal + 1], dp[bal] + a[i]);
            }
            // Close bracket
            if (bal > 0) {
                next[bal - 1] = Math.min(next[bal - 1], dp[bal] + b[i]);
            }
        }
        dp = next;
    }

    // If m == 1, answer is dp[0] (though m is even per constraints, m>=2 usually, but handle m=0? m>=1)
    // Constraints say m is even. If m=0, length 0, cost 0. m>=1.
    if (m === 1) {
        console.log(dp[0]);
        return;
    }

    // Transition matrix T for one period
    const size = n + 1;
    const T = [];
    for (let s = 0; s < size; s++) {
        T[s] = new Array(size).fill(INF);
    }
    for (let s = 0; s < size; s++) {
        // DP from start balance s
        let cur = new Array(size).fill(INF);
        cur[s] = 0;
        for (let i = 0; i < n; i++) {
            const next = new Array(size).fill(INF);
            for (let bal = 0; bal < size; bal++) {
                if (cur[bal] === INF) continue;
                if (bal + 1 < size) {
                    next[bal + 1] = Math.min(next[bal + 1], cur[bal] + a[i]);
                }
                if (bal > 0) {
                    next[bal - 1] = Math.min(next[bal - 1], cur[bal] + b[i]);
                }
            }
            cur = next;
        }
        for (let e = 0; e < size; e++) {
            T[s][e] = cur[e];
        }
    }

    // Min-plus matrix multiplication
    function multiply(A, B) {
        const sz = A.length;
        const C = [];
        for (let i = 0; i < sz; i++) {
            C[i] = new Array(sz).fill(INF);
        }
        for (let i = 0; i < sz; i++) {
            const Ai = A[i];
            const Ci = C[i];
            for (let k = 0; k < sz; k++) {
                const aik = Ai[k];
                if (aik === INF) continue;
                const Bk = B[k];
                for (let j = 0; j < sz; j++) {
                    const bkj = Bk[j];
                    if (bkj === INF) continue;
                    const val = aik + bkj;
                    if (val < Ci[j]) Ci[j] = val;
                }
            }
        }
        return C;
    }

    // Matrix exponentiation
    function matPow(mat, power) {
        const sz = mat.length;
        let res = [];
        for (let i = 0; i < sz; i++) {
            res[i] = new Array(sz).fill(INF);
            res[i][i] = 0;
        }
        let base = mat;
        while (power > 0) {
            if (power & 1) {
                res = multiply(res, base);
            }
            base = multiply(base, base);
            power >>= 1;
        }
        return res;
    }

    const Tm = matPow(T, m);
    const ans = Tm[0][0];
    console.log(ans);
}
